def findHeight(N, arr):
    def depth(node):
        if arr[node] == -1:
            return 0
        return 1 + depth(arr[node])

    max_height = 0
    for i in range(N):
        max_height = max(max_height, depth(i))

    return max_height

import sys
input = sys.stdin.read().split()
N = int(input[0])
arr = list(map(int, input[1:]))
print(findHeight(N, arr))
